<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/customer-inbox-core.php';
require_once __DIR__.'/includes/location-core.php';
$user=app_require_auth();
if(!app_has_permission('customer_promotions.manage',$user)){http_response_code(403);exit('Customer promotions permission required.');}
$pdo=app_pdo();
$org=(int)$user['organization_id'];
$error=null;$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!app_verify_csrf($_POST['csrf_token']??null)){$error='The promotion form expired. Refresh and try again.';}
    else{
        try{
            $sent=customer_inbox_send_promotion($pdo,$org,[
                'title'=>$_POST['title']??'','previewText'=>$_POST['preview_text']??'','bodyText'=>$_POST['body_text']??'',
                'ctaLabel'=>$_POST['cta_label']??'','ctaUrl'=>$_POST['cta_url']??'','promoCode'=>$_POST['promo_code']??'',
                'locationId'=>(int)($_POST['location_id']??0),'tagId'=>(int)($_POST['tag_id']??0),'expiresAt'=>$_POST['expires_at']??'',
            ],(int)$user['id']);
            $success='Promotion sent to '.number_format((int)$sent['recipientCount']).' customer inbox'.((int)$sent['recipientCount']===1?'':'es').'.';
            $_POST=[];
        }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'The promotion could not be sent.';error_log('Customer promotion failed: '.$e->getMessage());}
    }
}
$locations=location_list($pdo,$org,false);
$tags=customer_inbox_tags($pdo,$org);
$campaigns=customer_inbox_campaigns($pdo,$org,40);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer Promotions</title><style>
:root{--bg:#f3f2ed;--panel:#fff;--ink:#171815;--muted:#73766e;--line:#dfdfd7;--dark:#171b1a;--accent:#d94a2b;--good:#247653;--bad:#b43f36}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,textarea,select{font:inherit}.top{height:64px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:10px 16px;position:sticky;top:0;z-index:10}.brand strong{display:block}.brand small{display:block;color:var(--muted);font-size:10px;margin-top:2px}.top nav{display:flex;gap:7px}.btn{display:inline-flex;border:1px solid var(--line);background:#fff;color:var(--ink);padding:9px 12px;border-radius:10px;font-weight:800;text-decoration:none;font-size:11px;cursor:pointer}.btn.dark{background:var(--dark);border-color:var(--dark);color:#fff}.shell{width:min(1180px,calc(100% - 28px));margin:26px auto 70px;display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:18px;align-items:start}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 14px 34px rgba(20,22,18,.06)}.panel h1,.panel h2{margin:0}.panel h1{font-size:31px;letter-spacing:-.04em}.panel h2{font-size:16px}.intro{color:var(--muted);font-size:11px;line-height:1.55;margin:7px 0 20px;max-width:700px}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:5px}.field.wide{grid-column:1/-1}.field span{font-size:9px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:900}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);background:#fbfbf9;border-radius:10px;padding:10px;outline:0}.field textarea{min-height:150px;resize:vertical}.field input:focus,.field textarea:focus,.field select:focus{border-color:#a9aaa2}.help{font-size:9px;color:var(--muted);line-height:1.45}.message{border-radius:11px;padding:11px 12px;margin:0 0 14px;font-size:11px}.message.good{background:#e7f3eb;color:var(--good)}.message.bad{background:#f7e8e6;color:var(--bad)}.send{grid-column:1/-1;display:flex;justify-content:flex-end;margin-top:4px}.campaigns{display:grid;gap:8px;margin-top:14px}.campaign{border:1px solid var(--line);border-radius:12px;padding:12px}.campaign strong{font-size:12px;display:block}.campaign small{display:block;color:var(--muted);font-size:9px;line-height:1.5;margin-top:4px}.campaign .metrics{display:flex;gap:8px;margin-top:8px;font-size:9px}.campaign .metrics b{background:#f2f1ec;border-radius:999px;padding:4px 7px}.empty{color:var(--muted);font-size:11px;padding:22px 0;text-align:center}.privacy{border-top:1px solid var(--line);margin-top:18px;padding-top:14px;color:var(--muted);font-size:9px;line-height:1.55}@media(max-width:900px){.shell{grid-template-columns:1fr}.form{grid-template-columns:1fr}.field.wide,.send{grid-column:auto}}@media(max-width:540px){.top{height:auto;align-items:flex-start;gap:10px}.top nav{flex-wrap:wrap}.shell{width:min(100% - 18px,1180px);margin-top:12px}.panel{padding:15px;border-radius:15px}}
</style></head><body><header class="top"><div class="brand"><strong>Customer Inbox Promotions</strong><small>In-account offers only — email and SMS consent remain separate.</small></div><nav><a class="btn" href="customer-crm.php">Customer CRM</a><a class="btn" href="index.php">Dashboard</a></nav></header><main class="shell"><section class="panel"><h1>Send a promotion</h1><p class="intro">This creates a durable message in each eligible customer account Inbox. Customers can disable future Inbox promotions without affecting transactional order updates.</p><?php if($success):?><div class="message good"><?=app_escape($success)?></div><?php endif;?><?php if($error):?><div class="message bad"><?=app_escape($error)?></div><?php endif;?><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=app_escape(app_csrf_token())?>"><label class="field wide"><span>Title</span><input name="title" maxlength="180" value="<?=app_escape($_POST['title']??'')?>" placeholder="Tuesday pizza + gelato offer" required></label><label class="field wide"><span>Inbox preview</span><input name="preview_text" maxlength="320" value="<?=app_escape($_POST['preview_text']??'')?>" placeholder="Short line shown before the full message"></label><label class="field wide"><span>Message</span><textarea name="body_text" maxlength="12000" placeholder="Write the offer in plain language." required><?=app_escape($_POST['body_text']??'')?></textarea></label><label class="field"><span>Promo code</span><input name="promo_code" maxlength="80" value="<?=app_escape($_POST['promo_code']??'')?>" placeholder="STONE10"></label><label class="field"><span>Expires</span><input name="expires_at" type="datetime-local" value="<?=app_escape($_POST['expires_at']??'')?>"></label><label class="field"><span>Location</span><select name="location_id"><option value="0">All locations / general</option><?php foreach($locations as $location):?><option value="<?=app_escape((string)$location['id'])?>" <?=((int)($_POST['location_id']??0)===(int)$location['id'])?'selected':''?>><?=app_escape((string)$location['name'])?></option><?php endforeach;?></select></label><label class="field"><span>Audience</span><select name="tag_id"><option value="0">All Inbox-enabled customer accounts</option><?php foreach($tags as $tag):?><option value="<?=app_escape((string)$tag['id'])?>" <?=((int)($_POST['tag_id']??0)===(int)$tag['id'])?'selected':''?>>Tag: <?=app_escape((string)$tag['name'])?></option><?php endforeach;?></select><small class="help">Use CRM tags for targeted promotions, such as Online Customer or VIP.</small></label><label class="field"><span>Button label</span><input name="cta_label" maxlength="80" value="<?=app_escape($_POST['cta_label']??'Order online')?>"></label><label class="field"><span>Button destination</span><input name="cta_url" maxlength="500" value="<?=app_escape($_POST['cta_url']??'online-order.php')?>"><small class="help">For safety, promotion buttons must link to a relative Stonefellows page.</small></label><div class="send"><button class="btn dark" type="submit">Send to customer Inboxes</button></div></form><p class="privacy">This page does not send email or SMS. External marketing channels continue to use the append-only CRM consent records. Order confirmations and future order-status messages are transactional and are not disabled when a customer turns off Inbox promotions.</p></section><aside class="panel"><h2>Recent Inbox promotions</h2><div class="campaigns"><?php if($campaigns):foreach($campaigns as $campaign):$recipients=(int)$campaign['recipient_count'];$reads=(int)$campaign['read_count'];?><article class="campaign"><strong><?=app_escape((string)$campaign['title'])?></strong><small><?=app_escape((string)($campaign['location_name']?:'All locations'))?> · <?=app_escape(substr((string)$campaign['sent_at'],0,16))?><?php if($campaign['promo_code']):?> · Code <?=app_escape((string)$campaign['promo_code'])?><?php endif;?></small><div class="metrics"><b><?=number_format($recipients)?> delivered</b><b><?=number_format($reads)?> read</b></div></article><?php endforeach;else:?><div class="empty">No customer Inbox promotions have been sent yet.</div><?php endif;?></div></aside></main></body></html>
